/*
class Node {
public:
    int val;
    Node* left;
    Node* right;
    Node* parent;
};
*/

class Solution {
public:
    Node* inorderSuccessor(Node* node) {
        if (!node) return nullptr;
        if (node->right) {
            Node* curr = node->right;
            while (curr->left) curr = curr->left;
            return curr;
        }
        Node* curr = node;
        while (curr->parent && curr == curr->parent->right) {
            curr = curr->parent;
        }
        return curr->parent;
    }
};

/*
class Node {
    public int val;
    public Node left;
    public Node right;
    public Node parent;
};
*/

class Solution {
    public Node inorderSuccessor(Node node) {
        if (node == null) return null;
        if (node.right != null) {
            Node curr = node.right;
            while (curr.left != null) curr = curr.left;
            return curr;
        }
        Node curr = node;
        while (curr.parent != null && curr == curr.parent.right) {
            curr = curr.parent;
        }
        return curr.parent;
    }
}

/**
 * // Definition for a Node.
 * function Node(val) {
 *    this.val = val;
 *    this.left = null;
 *    this.right = null;
 *    this.parent = null;
 * };
 */

/**
 * @param {Node} node
 * @return {Node}
 */
var inorderSuccessor = function(node) {
    if (!node) return null;
    if (node.right) {
        let curr = node.right;
        while (curr.left) curr = curr.left;
        return curr;
    }
    let curr = node;
    while (curr.parent && curr === curr.parent.right) {
        curr = curr.parent;
    }
    return curr.parent;
};
